-- Baseline generated from current Sequelize models, without tenant data.
-- Empty databases only; reviewed forward migrations own subsequent changes.
SET FOREIGN_KEY_CHECKS=0;
CREATE TABLE IF NOT EXISTS `ac_attempts` (`uid` INTEGER auto_increment , `vpbx_user_uid` INTEGER NOT NULL, `task_uid` INTEGER NOT NULL, `campaign_uid` INTEGER NOT NULL, `attempt_no` INTEGER NOT NULL DEFAULT 1, `started_at` DATETIME NOT NULL, `answered_at` DATETIME, `ended_at` DATETIME, `duration` INTEGER NOT NULL DEFAULT 0, `billsec` INTEGER NOT NULL DEFAULT 0, `disposition` VARCHAR(24) NOT NULL DEFAULT 'dialing', `hangup_cause` VARCHAR(64), `trunk_id` VARCHAR(128), `caller_id` VARCHAR(64), `channel_id` VARCHAR(128), `uniqueid` VARCHAR(64), `linkedid` VARCHAR(64), `amd_result` VARCHAR(32), `queue_name` VARCHAR(128), `agent_interface` VARCHAR(128), `talk_sec` INTEGER NOT NULL DEFAULT 0, `scenario_result` JSON, PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `ac_base_fields` (`uid` INTEGER auto_increment , `base_uid` INTEGER NOT NULL, `key` VARCHAR(64) NOT NULL, `label` VARCHAR(255) NOT NULL, `type` VARCHAR(16) NOT NULL, `required` TINYINT(1) NOT NULL DEFAULT false, `position` INTEGER NOT NULL DEFAULT 0, `is_phone` TINYINT(1) NOT NULL DEFAULT false, `var_name` VARCHAR(64) NOT NULL DEFAULT '', `enum_values` JSON, PRIMARY KEY (`uid`), FOREIGN KEY (`base_uid`) REFERENCES `ac_bases` (`uid`) ON DELETE NO ACTION ON UPDATE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `ac_bases` (`uid` INTEGER auto_increment , `vpbx_user_uid` INTEGER NOT NULL, `name` VARCHAR(255) NOT NULL, `description` VARCHAR(512) NOT NULL DEFAULT '', `dedup_policy` VARCHAR(16) NOT NULL DEFAULT 'phone', `phone_normalization` VARCHAR(16) NOT NULL DEFAULT 'ru_8_to_7', `revision` INTEGER NOT NULL DEFAULT 0, `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL, PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `ac_campaigns` (`uid` INTEGER auto_increment , `vpbx_user_uid` INTEGER NOT NULL, `name` VARCHAR(255) NOT NULL, `status` VARCHAR(16) NOT NULL DEFAULT 'draft', `dial_mode` VARCHAR(16) NOT NULL DEFAULT 'progressive', `base_uid` INTEGER NOT NULL, `pacing` JSON NOT NULL, `retry` JSON NOT NULL, `trunk_pool` JSON NOT NULL, `cid_policy` JSON NOT NULL, `queue_names` JSON NOT NULL, `scenario_actions` JSON NOT NULL, `amd` JSON NOT NULL, `success_min_sec` INTEGER NOT NULL DEFAULT 15, `dial_timeout_sec` INTEGER NOT NULL DEFAULT 45, `revision` INTEGER NOT NULL DEFAULT 0, `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL, PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `ac_contact_phones` (`uid` INTEGER auto_increment , `contact_uid` INTEGER NOT NULL, `base_uid` INTEGER NOT NULL, `raw` VARCHAR(64) NOT NULL, `normalized` VARCHAR(64) NOT NULL, `position` INTEGER NOT NULL DEFAULT 0, `is_primary` TINYINT(1) NOT NULL DEFAULT false, `tz_offset_min` INTEGER NOT NULL DEFAULT 180, PRIMARY KEY (`uid`), FOREIGN KEY (`contact_uid`) REFERENCES `ac_contacts` (`uid`) ON DELETE NO ACTION ON UPDATE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `ac_contacts` (`uid` INTEGER auto_increment , `base_uid` INTEGER NOT NULL, `vpbx_user_uid` INTEGER NOT NULL, `external_id` VARCHAR(128), `values` JSON NOT NULL, `comment` VARCHAR(512) NOT NULL DEFAULT '', `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL, PRIMARY KEY (`uid`), FOREIGN KEY (`base_uid`) REFERENCES `ac_bases` (`uid`) ON DELETE CASCADE ON UPDATE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `ac_daily_campaign_stats` (`uid` INTEGER auto_increment , `vpbx_user_uid` INTEGER NOT NULL, `campaign_uid` INTEGER NOT NULL, `day` DATE NOT NULL, `dials` INTEGER NOT NULL DEFAULT 0, `answered` INTEGER NOT NULL DEFAULT 0, `success` INTEGER NOT NULL DEFAULT 0, `short` INTEGER NOT NULL DEFAULT 0, `no_answer` INTEGER NOT NULL DEFAULT 0, `busy` INTEGER NOT NULL DEFAULT 0, `amd` INTEGER NOT NULL DEFAULT 0, `failed` INTEGER NOT NULL DEFAULT 0, `talk_sec_sum` INTEGER NOT NULL DEFAULT 0, `billsec_sum` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `ac_dnc` (`uid` INTEGER auto_increment , `vpbx_user_uid` INTEGER NOT NULL, `scope` VARCHAR(16) NOT NULL DEFAULT 'global', `scope_uid` INTEGER, `normalized_phone` VARCHAR(64) NOT NULL, `reason` VARCHAR(255) NOT NULL DEFAULT '', `source` VARCHAR(64) NOT NULL DEFAULT 'manual', `expires_at` DATETIME, `created_at` DATETIME NOT NULL, PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `ac_import_profiles` (`uid` INTEGER auto_increment , `base_uid` INTEGER NOT NULL, `vpbx_user_uid` INTEGER NOT NULL, `name` VARCHAR(255) NOT NULL, `source` VARCHAR(8) NOT NULL DEFAULT 'csv', `delimiter` VARCHAR(4) NOT NULL DEFAULT ';', `encoding` VARCHAR(32) NOT NULL DEFAULT 'utf-8', `has_header` TINYINT(1) NOT NULL DEFAULT true, `column_map` JSON NOT NULL, `dedup_policy` VARCHAR(16) NOT NULL DEFAULT 'phone', `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL, PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `ac_import_runs` (`uid` INTEGER auto_increment , `base_uid` INTEGER NOT NULL, `vpbx_user_uid` INTEGER NOT NULL, `profile_uid` INTEGER, `filename` VARCHAR(512) NOT NULL DEFAULT '', `total_rows` INTEGER NOT NULL DEFAULT 0, `imported` INTEGER NOT NULL DEFAULT 0, `skipped` INTEGER NOT NULL DEFAULT 0, `errors` JSON, `created_at` DATETIME NOT NULL, PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `ac_schedules` (`uid` INTEGER auto_increment , `campaign_uid` INTEGER NOT NULL, `kind` VARCHAR(16) NOT NULL DEFAULT 'weekly', `weekday` TINYINT, `time_from` VARCHAR(5) NOT NULL DEFAULT '09:00', `time_to` VARCHAR(5) NOT NULL DEFAULT '21:00', `timezone` VARCHAR(64) NOT NULL DEFAULT 'Europe/Moscow', `date_from` DATE, `date_to` DATE, `enabled` TINYINT(1) NOT NULL DEFAULT true, PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `ac_tasks` (`uid` INTEGER auto_increment , `vpbx_user_uid` INTEGER NOT NULL, `campaign_uid` INTEGER NOT NULL, `contact_uid` INTEGER NOT NULL, `phone_uid` INTEGER NOT NULL, `status` VARCHAR(16) NOT NULL DEFAULT 'pending', `attempt_count` INTEGER NOT NULL DEFAULT 0, `next_attempt_at` DATETIME, `last_disposition` VARCHAR(24) NOT NULL DEFAULT 'new', `last_cause` VARCHAR(64), `leased_by` VARCHAR(64), `leased_at` DATETIME, `priority` INTEGER NOT NULL DEFAULT 0, `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL, PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `action_logs` (`id` INTEGER auto_increment , `user_id` INTEGER NOT NULL, `action` VARCHAR(64) NOT NULL, `entity_type` VARCHAR(64) NOT NULL, `entity_id` INTEGER, `details` TEXT, `vpbx_user_uid` INTEGER NOT NULL, `status` VARCHAR(16) NOT NULL DEFAULT 'success', `created_at` DATETIME, PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `ai_agent_proposals` (`proposal_id` CHAR(36) , `thread_uid` INTEGER NOT NULL, `vpbx_user_uid` INTEGER NOT NULL, `user_uid` INTEGER NOT NULL, `entity_type` VARCHAR(64) NOT NULL, `entity_label` VARCHAR(255) NOT NULL, `summary` JSON NOT NULL, `before_json` JSON, `after_json` JSON, `apply_payload` JSON NOT NULL, `includes_dialplan_reload` TINYINT(1) NOT NULL DEFAULT false, `status` VARCHAR(16) NOT NULL DEFAULT 'pending', `error` TEXT, `expires_at` DATETIME NOT NULL, `applied_at` DATETIME DEFAULT NULL, `created_at` DATETIME NOT NULL, PRIMARY KEY (`proposal_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `ai_agent_thread_messages` (`uid` BIGINT auto_increment , `thread_uid` INTEGER NOT NULL, `vpbx_user_uid` INTEGER NOT NULL, `role` VARCHAR(16) NOT NULL, `content` TEXT, `tool_name` VARCHAR(128) DEFAULT NULL, `tool_calls` JSON, `proposal_id` CHAR(36) DEFAULT NULL, `tool_call_id` VARCHAR(128) DEFAULT NULL, `provider_model` VARCHAR(128) DEFAULT NULL, `close_kind` VARCHAR(16) DEFAULT NULL, `visibility` VARCHAR(16) NOT NULL DEFAULT 'public', `reasoning` TEXT, `tokens_in` INTEGER NOT NULL DEFAULT 0, `tokens_out` INTEGER NOT NULL DEFAULT 0, `created_at` DATETIME NOT NULL, PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `ai_agent_threads` (`uid` INTEGER auto_increment , `vpbx_user_uid` INTEGER NOT NULL, `user_uid` INTEGER NOT NULL, `title` VARCHAR(255) NOT NULL DEFAULT '', `status` VARCHAR(16) NOT NULL DEFAULT 'active', `provider_uid` INTEGER DEFAULT NULL, `tokens_in` INTEGER NOT NULL DEFAULT 0, `tokens_out` INTEGER NOT NULL DEFAULT 0, `brief_json` JSON, `brief_version` INTEGER NOT NULL DEFAULT 0, `brief_updated_through_message_uid` BIGINT DEFAULT NULL, `last_message_at` DATETIME DEFAULT NULL, `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL, PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `ai_agent_workflow_steps` (`uid` INTEGER auto_increment , `workflow_uid` INTEGER NOT NULL, `step_key` VARCHAR(64) NOT NULL, `step_index` INTEGER NOT NULL DEFAULT 0, `tool` VARCHAR(128) NOT NULL, `entity_type` VARCHAR(64) NOT NULL DEFAULT '', `entity_label` VARCHAR(255) NOT NULL DEFAULT '', `depends_on` JSON NOT NULL, `canonical_args` JSON NOT NULL, `schema_version` VARCHAR(64) NOT NULL, `before_json` JSON, `after_json` JSON, `result_json` JSON, `status` VARCHAR(16) NOT NULL DEFAULT 'pending', `attempts` INTEGER NOT NULL DEFAULT 0, `error` TEXT, `requires_secure_input` TINYINT(1) NOT NULL DEFAULT false, `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL, PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `ai_agent_workflows` (`uid` INTEGER auto_increment , `workflow_id` CHAR(36) NOT NULL UNIQUE, `thread_uid` INTEGER NOT NULL, `vpbx_user_uid` INTEGER NOT NULL, `user_uid` INTEGER NOT NULL, `brief_version` INTEGER NOT NULL DEFAULT 0, `title` VARCHAR(255) NOT NULL DEFAULT '', `summary` JSON NOT NULL, `status` VARCHAR(16) NOT NULL DEFAULT 'pending', `error` TEXT, `expires_at` DATETIME NOT NULL, `applied_at` DATETIME DEFAULT NULL, `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL, PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `ai_chat_settings` (`uid` INTEGER auto_increment , `user_uid` INTEGER NOT NULL UNIQUE, `confirm_destructive` TINYINT NOT NULL DEFAULT 0, `settings` JSON, `created_at` DATETIME, `updated_at` DATETIME, PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `billing_balances` (`id` INTEGER auto_increment , `tenant_id` INTEGER NOT NULL UNIQUE, `balance_kopecks` BIGINT DEFAULT 0, `credit_limit_kopecks` BIGINT DEFAULT 0, `currency` VARCHAR(3) DEFAULT 'RUB', `is_blocked` TINYINT(1) DEFAULT false, `blocked_at` DATETIME, `updated_at` DATETIME, PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `billing_transactions` (`id` BIGINT auto_increment , `tenant_id` INTEGER NOT NULL, `type` ENUM('deposit', 'charge', 'refund', 'correction') NOT NULL, `amount_kopecks` BIGINT NOT NULL, `balance_before` BIGINT NOT NULL, `balance_after` BIGINT NOT NULL, `description` VARCHAR(512), `module_code` VARCHAR(64), `performed_by` INTEGER, `external_id` VARCHAR(128) UNIQUE, `doc_number` INTEGER, `sbis_id` VARCHAR(128), `sbis_url` TEXT, `sbis_status` ENUM('pending', 'done', 'failed'), `sbis_doc_num` VARCHAR(64), `created_at` DATETIME, PRIMARY KEY (`id`), INDEX `idx_bt_tenant_date` (`tenant_id`, `created_at`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `call_group_members` (`uid` INTEGER auto_increment , `call_group_uid` INTEGER NOT NULL, `member_type` ENUM('internal', 'external') NOT NULL, `value` VARCHAR(128) NOT NULL, `position` INTEGER NOT NULL DEFAULT 0, `ring_time` INTEGER NOT NULL DEFAULT 20, `vpbx_user_uid` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `call_groups` (`uid` INTEGER auto_increment , `name` VARCHAR(128) NOT NULL, `exten` VARCHAR(8) NOT NULL, `strategy` ENUM('ringall', 'hunt', 'memoryhunt', 'random') NOT NULL, `ring_time` INTEGER NOT NULL DEFAULT 25, `external_context` VARCHAR(128), `cid_prefix` VARCHAR(64), `vpbx_user_uid` INTEGER NOT NULL DEFAULT 0, `confirm_external` TINYINT(1) NOT NULL DEFAULT false, `confirm_digit` VARCHAR(1) NOT NULL DEFAULT '1', `skip_busy` TINYINT(1) NOT NULL DEFAULT false, `greeting_prompt` VARCHAR(128), `moh_class` VARCHAR(64), `use_moh_instead_of_ringback` TINYINT(1) NOT NULL DEFAULT false, `dial_options` VARCHAR(64) NOT NULL DEFAULT 'tT', PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `cc_agent_events` (`uid` BIGINT auto_increment , `session_id` INTEGER NOT NULL, `user_id` INTEGER NOT NULL, `event_type` ENUM('LOGIN', 'LOGOUT', 'READY', 'PAUSE', 'CALL_START', 'CALL_END', 'WRAPUP_START', 'WRAPUP_END', 'HOLD', 'UNHOLD', 'DIALING', 'CONSULT', 'ACW') NOT NULL, `reason` VARCHAR(128) DEFAULT '', `call_uniqueid` VARCHAR(64) DEFAULT '', `caller_id` VARCHAR(32) DEFAULT '', `queue_name` VARCHAR(64) DEFAULT '', `duration` INTEGER DEFAULT 0, `created_at` DATETIME, `vpbx_user_uid` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `cc_agent_queues` (`uid` INTEGER auto_increment , `user_id` INTEGER NOT NULL, `agent_interface` VARCHAR(64) NOT NULL, `queue_name` VARCHAR(64) NOT NULL, `penalty` INTEGER DEFAULT 0, `user_uid` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `cc_agent_sessions` (`uid` INTEGER auto_increment , `user_id` INTEGER NOT NULL, `agent_interface` VARCHAR(64) NOT NULL, `login_time` DATETIME, `logout_time` DATETIME, `total_calls` INTEGER DEFAULT 0, `total_talk_time` INTEGER DEFAULT 0, `total_pause_time` INTEGER DEFAULT 0, `total_idle_time` INTEGER DEFAULT 0, `last_status` VARCHAR(32), `last_status_at` DATETIME, `pause_reason` VARCHAR(128), `last_status_origin` VARCHAR(16), `queues_snapshot` JSON, `softphone_mode` VARCHAR(16), `panel_seen_at` DATETIME, `close_reason` VARCHAR(32), `vpbx_user_uid` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `cc_ai_agents` (`uid` INTEGER auto_increment , `name` VARCHAR(128) NOT NULL, `unique_id` VARCHAR(64) NOT NULL, `mode` ENUM('realtime', 'cascade') NOT NULL DEFAULT 'realtime', `voice` VARCHAR(64) DEFAULT '', `greeting` TEXT, `instruction` MEDIUMTEXT, `model_profile_id` INTEGER, `stt_profile_id` INTEGER, `tts_profile_id` INTEGER, `vad_config` JSON, `toolset_id` INTEGER, `channel_kind` ENUM('local', 'pjsip') NOT NULL DEFAULT 'local', `enabled` TINYINT(1) NOT NULL DEFAULT true, `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL, `vpbx_user_uid` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `cc_ai_audit_log` (`uid` BIGINT auto_increment , `call_uniqueid` VARCHAR(64), `thread_uid` INTEGER DEFAULT NULL, `agent_uid` INTEGER, `tool_name` VARCHAR(128) NOT NULL, `args` JSON, `result` JSON, `duration_ms` INTEGER DEFAULT 0, `status` ENUM('ok', 'error', 'rate_limited', 'denied') NOT NULL DEFAULT 'ok', `created_at` DATETIME NOT NULL, `vpbx_user_uid` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `cc_ai_billing` (`uid` BIGINT auto_increment , `period` DATE NOT NULL, `total_calls` INTEGER NOT NULL DEFAULT 0, `total_tokens_in` BIGINT NOT NULL DEFAULT 0, `total_tokens_out` BIGINT NOT NULL DEFAULT 0, `total_audio_seconds` BIGINT NOT NULL DEFAULT 0, `total_cost` DECIMAL(14,4) NOT NULL DEFAULT 0, `currency` VARCHAR(8) NOT NULL DEFAULT 'USD', `vpbx_user_uid` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `cc_ai_cdr` (`uid` BIGINT auto_increment , `call_uniqueid` VARCHAR(64) NOT NULL, `agent_uid` INTEGER NOT NULL, `provider_uid` INTEGER, `queue` VARCHAR(64) DEFAULT '', `pipeline_mode` ENUM('realtime', 'cascade') NOT NULL, `started_at` DATETIME NOT NULL, `ended_at` DATETIME, `duration_sec` INTEGER NOT NULL DEFAULT 0, `tokens_in` INTEGER NOT NULL DEFAULT 0, `tokens_out` INTEGER NOT NULL DEFAULT 0, `audio_seconds` INTEGER NOT NULL DEFAULT 0, `tool_calls` JSON, `cost_input` DECIMAL(10,4) NOT NULL DEFAULT 0, `cost_output` DECIMAL(10,4) NOT NULL DEFAULT 0, `cost_audio` DECIMAL(10,4) NOT NULL DEFAULT 0, `cost_total` DECIMAL(10,4) NOT NULL DEFAULT 0, `currency` VARCHAR(8) NOT NULL DEFAULT 'USD', `recording_ref` VARCHAR(255) DEFAULT '', `transcript_ref` VARCHAR(255) DEFAULT '', `vpbx_user_uid` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `cc_ai_invoices` (`uid` INTEGER auto_increment , `invoice_number` VARCHAR(64) NOT NULL, `period_from` DATE NOT NULL, `period_to` DATE NOT NULL, `total_amount` DECIMAL(14,4) NOT NULL DEFAULT 0, `currency` VARCHAR(8) NOT NULL DEFAULT 'USD', `status` ENUM('draft', 'issued', 'paid', 'void') NOT NULL DEFAULT 'draft', `pdf_ref` VARCHAR(512), `created_at` DATETIME NOT NULL, `vpbx_user_uid` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `cc_ai_providers` (`uid` INTEGER auto_increment , `name` VARCHAR(128) NOT NULL, `kind` ENUM('online', 'local', 'custom') NOT NULL, `vendor` VARCHAR(32) NOT NULL, `endpoint` VARCHAR(512) NOT NULL, `auth_type` ENUM('bearer', 'api_key_header', 'none', 'custom') DEFAULT 'bearer', `encrypted_api_key` TEXT, `capabilities` JSON NOT NULL, `defaults` JSON, `pricing` JSON NOT NULL, `enabled` TINYINT(1) NOT NULL DEFAULT true, `vpbx_user_uid` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `cc_ai_toolsets` (`uid` INTEGER auto_increment , `name` VARCHAR(128) NOT NULL, `description` TEXT, `tools` JSON NOT NULL, `vpbx_user_uid` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `cc_alert_config` (`uid` INTEGER auto_increment , `integration_uid` INTEGER, `target` VARCHAR(255), `enabled` TINYINT(1) NOT NULL DEFAULT false, `cooldown_sec` INTEGER NOT NULL DEFAULT 300, `updated_at` DATETIME NOT NULL, `vpbx_user_uid` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `cc_callback_requests` (`uid` INTEGER auto_increment , `vpbx_user_uid` INTEGER NOT NULL DEFAULT 0, `caller` VARCHAR(64) NOT NULL DEFAULT '', `route_uid` INTEGER, `queue_uid` INTEGER, `queue_name` VARCHAR(64), `step_id` VARCHAR(64), `uniqueid` VARCHAR(128), `status` VARCHAR(16) NOT NULL DEFAULT 'pending', `attempt_count` INTEGER NOT NULL DEFAULT 0, `max_attempts` INTEGER NOT NULL DEFAULT 3, `pause_minutes` INTEGER NOT NULL DEFAULT 30, `next_attempt_at` DATETIME, `window_start` VARCHAR(5) NOT NULL DEFAULT '09:00', `window_end` VARCHAR(5) NOT NULL DEFAULT '21:00', `claimed_agent_uid` INTEGER, `source` VARCHAR(24) NOT NULL DEFAULT 'route_step', `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL, PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `cc_card_data` (`uid` BIGINT auto_increment , `template_id` INTEGER NOT NULL, `call_uniqueid` VARCHAR(64) DEFAULT '', `caller_id` VARCHAR(32) DEFAULT '', `queue_name` VARCHAR(64) DEFAULT '', `agent_user_uid` INTEGER, `status` ENUM('draft', 'saved', 'missed', 'callback_done') NOT NULL DEFAULT 'saved', `field_values` JSON NOT NULL, `created_at` DATETIME NOT NULL, `updated_at` DATETIME, `vpbx_user_uid` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `cc_card_fields` (`uid` INTEGER auto_increment , `template_id` INTEGER NOT NULL, `field_key` VARCHAR(64) NOT NULL, `field_type` ENUM('text', 'textarea', 'phone', 'email', 'select', 'multi_select', 'date', 'datetime', 'number', 'checkbox', 'phonebook_lookup', 'divider', 'heading', 'readonly') NOT NULL, `label` VARCHAR(128) NOT NULL, `placeholder` VARCHAR(256) DEFAULT '', `is_required` TINYINT(1) NOT NULL DEFAULT false, `default_value` VARCHAR(256) DEFAULT '', `options` JSON, `depends_on` VARCHAR(64), `depends_values` JSON, `sort_order` INTEGER NOT NULL DEFAULT 0, `width` ENUM('full', 'half') NOT NULL DEFAULT 'full', `auto_populate` VARCHAR(64), `vpbx_user_uid` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `cc_card_templates` (`uid` INTEGER auto_increment , `name` VARCHAR(128) NOT NULL, `description` TEXT, `is_active` TINYINT(1) NOT NULL DEFAULT true, `auto_open_on` ENUM('answer', 'ring', 'manual') NOT NULL DEFAULT 'answer', `auto_save_on_timeout` TINYINT(1) NOT NULL DEFAULT true, `webhook_integration_uid` INTEGER DEFAULT NULL, `webhook_field_map` JSON, `queue_names` JSON, `created_at` DATETIME NOT NULL, `updated_at` DATETIME, `vpbx_user_uid` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `cc_chat_channels` (`uid` BIGINT auto_increment , `channel_key` VARCHAR(128) NOT NULL, `type` ENUM('direct', 'group', 'broadcast_all', 'broadcast_queue') NOT NULL, `name` VARCHAR(128), `member_user_ids` JSON, `queue_name` VARCHAR(64), `created_by` INTEGER NOT NULL, `created_at` DATETIME NOT NULL, `vpbx_user_uid` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `cc_chat_messages` (`uid` BIGINT auto_increment , `channel_key` VARCHAR(128) NOT NULL, `channel_type` ENUM('direct', 'group', 'broadcast_all', 'broadcast_queue') NOT NULL, `sender_user_id` INTEGER NOT NULL, `sender_name` VARCHAR(128), `body` TEXT NOT NULL, `created_at` DATETIME NOT NULL, `vpbx_user_uid` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `cc_contacts` (`uid` BIGINT auto_increment , `vpbx_user_uid` INTEGER NOT NULL DEFAULT 0, `created_by` INTEGER NOT NULL, `name` VARCHAR(128) NOT NULL, `number` VARCHAR(64) NOT NULL, `note` VARCHAR(255) DEFAULT NULL, `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL, PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `cc_daily_agent_stats` (`uid` BIGINT auto_increment , `stat_date` DATE NOT NULL, `agent_interface` VARCHAR(64) NOT NULL, `agent_user_uid` INTEGER, `calls_handled` INTEGER NOT NULL DEFAULT 0, `total_talk_sec` INTEGER NOT NULL DEFAULT 0, `total_hold_sec` INTEGER NOT NULL DEFAULT 0, `total_wrapup_sec` INTEGER NOT NULL DEFAULT 0, `avg_handle_sec` INTEGER NOT NULL DEFAULT 0, `created_at` DATETIME NOT NULL, `vpbx_user_uid` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `cc_daily_queue_stats` (`uid` BIGINT auto_increment , `stat_date` DATE NOT NULL, `queue_name` VARCHAR(64) NOT NULL, `total_calls` INTEGER NOT NULL DEFAULT 0, `answered_calls` INTEGER NOT NULL DEFAULT 0, `abandoned_calls` INTEGER NOT NULL DEFAULT 0, `sla_met_calls` INTEGER NOT NULL DEFAULT 0, `avg_wait_sec` INTEGER NOT NULL DEFAULT 0, `avg_talk_sec` INTEGER NOT NULL DEFAULT 0, `avg_hold_sec` INTEGER NOT NULL DEFAULT 0, `max_wait_sec` INTEGER NOT NULL DEFAULT 0, `total_talk_sec` INTEGER NOT NULL DEFAULT 0, `created_at` DATETIME NOT NULL, `vpbx_user_uid` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `cc_display_tokens` (`uid` INTEGER auto_increment , `token` VARCHAR(64) NOT NULL, `label` VARCHAR(128), `created_by` INTEGER, `expires_at` DATETIME, `revoked_at` DATETIME, `last_used_at` DATETIME, `created_at` DATETIME NOT NULL, `vpbx_user_uid` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `cc_districts` (`uid` INTEGER auto_increment , `territorial_zone` VARCHAR(128) NOT NULL, `district` VARCHAR(128) NOT NULL, `sort_order` INTEGER DEFAULT 0, `is_active` TINYINT(1) DEFAULT true, PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `cc_missed_calls` (`uid` BIGINT auto_increment , `call_uniqueid` VARCHAR(64) NOT NULL UNIQUE, `queue_name` VARCHAR(64) NOT NULL, `caller_id_num` VARCHAR(32) NOT NULL DEFAULT '', `caller_id_name` VARCHAR(128) DEFAULT '', `hold_time` INTEGER DEFAULT 0, `position` INTEGER DEFAULT 0, `called_back` TINYINT(1) NOT NULL DEFAULT false, `called_back_by` INTEGER, `called_back_at` DATETIME, `note` VARCHAR(255) DEFAULT '', `client_called_back` TINYINT(1) NOT NULL DEFAULT false, `personal` TINYINT(1) NOT NULL DEFAULT false, `created_at` DATETIME NOT NULL, `vpbx_user_uid` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `cc_operator_settings` (`uid` INTEGER auto_increment , `operator_user_id` INTEGER NOT NULL, `pickup_enabled` TINYINT(1) NOT NULL DEFAULT false, `auto_answer` TINYINT(1) NOT NULL DEFAULT false, `auto_answer_zip_tone` TINYINT(1) NOT NULL DEFAULT true, `wrapup_timeout` INTEGER NOT NULL DEFAULT 30, `wrapup_extend_step` INTEGER NOT NULL DEFAULT 30, `wrapup_autosave_draft` TINYINT(1) NOT NULL DEFAULT true, `sound_incoming` TINYINT(1) NOT NULL DEFAULT true, `sound_missed` TINYINT(1) NOT NULL DEFAULT true, `notifications_enabled` TINYINT(1) NOT NULL DEFAULT true, `volume` INTEGER NOT NULL DEFAULT 100, `updated_at` DATETIME NOT NULL, `can_spy` TINYINT(1) NOT NULL DEFAULT false, `spyable` TINYINT(1) NOT NULL DEFAULT true, `click_to_call` TINYINT(1) NOT NULL DEFAULT true, `customize_ui` TINYINT(1) NOT NULL DEFAULT false, `spy_modes` JSON NOT NULL, `ui_visibility` JSON, `softphone_placement` VARCHAR(16) NOT NULL DEFAULT 'bottom-right', `notification_matrix` JSON, `supervised_agent_extens` JSON, `vpbx_user_uid` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `cc_pause_reasons` (`uid` INTEGER auto_increment , `name` VARCHAR(128) NOT NULL, `color` VARCHAR(7) DEFAULT '#f59e0b', `max_duration` INTEGER DEFAULT 0, `is_paid` TINYINT(1) DEFAULT true, `sort_order` INTEGER DEFAULT 0, `vpbx_user_uid` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `cc_queue_calls` (`uid` BIGINT auto_increment , `call_uniqueid` VARCHAR(64) NOT NULL, `queue_name` VARCHAR(64) NOT NULL, `agent_interface` VARCHAR(64) DEFAULT '', `agent_user_uid` INTEGER, `caller_id_num` VARCHAR(32) NOT NULL DEFAULT '', `caller_id_name` VARCHAR(128) DEFAULT '', `enter_time` DATETIME, `answer_time` DATETIME, `end_time` DATETIME, `wait_time` INTEGER NOT NULL DEFAULT 0, `talk_time` INTEGER NOT NULL DEFAULT 0, `hold_time` INTEGER NOT NULL DEFAULT 0, `wrapup_time` INTEGER NOT NULL DEFAULT 0, `disposition` ENUM('answered', 'abandoned', 'transferred', 'timeout', 'other') NOT NULL DEFAULT 'other', `transfer_destination` VARCHAR(64) DEFAULT '', `position` INTEGER NOT NULL DEFAULT 0, `direction` VARCHAR(16) NOT NULL DEFAULT 'inbound', `call_type` VARCHAR(32) DEFAULT '', `created_at` DATETIME NOT NULL, `vpbx_user_uid` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `cc_report_schedules` (`uid` BIGINT auto_increment , `name` VARCHAR(128) NOT NULL, `report_id` VARCHAR(32) NOT NULL, `format` ENUM('csv', 'xlsx') NOT NULL DEFAULT 'xlsx', `period_preset` ENUM('today', 'yesterday', 'last-7-days', 'last-30-days', 'previous-month') NOT NULL DEFAULT 'yesterday', `filters` JSON, `frequency` ENUM('daily', 'weekly', 'monthly') NOT NULL DEFAULT 'daily', `hour` INTEGER NOT NULL DEFAULT 8, `minute` INTEGER NOT NULL DEFAULT 0, `day_of_week` INTEGER, `day_of_month` INTEGER, `integration_uid` INTEGER NOT NULL, `target` VARCHAR(256), `subject_template` VARCHAR(256), `message_template` TEXT, `enabled` TINYINT(1) NOT NULL DEFAULT true, `last_run_at` DATETIME, `last_status` VARCHAR(16), `last_error` VARCHAR(512), `next_run_at` DATETIME, `vpbx_user_uid` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `cc_settings` (`uid` INTEGER auto_increment , `default_sla_threshold` INTEGER NOT NULL DEFAULT 20, `journal_depth` INTEGER NOT NULL DEFAULT 50, `alert_thresholds` JSON, `alert_sound_enabled` TINYINT(1) NOT NULL DEFAULT true, `role_permission_defaults` JSON, `permission_locks` JSON, `ui_visibility_defaults` JSON, `ui_visibility_locks` JSON, `notification_defaults` JSON, `notification_locks` JSON, `autopause_rules` JSON, `autopause_enabled` TINYINT(1) NOT NULL DEFAULT true, `shift_policy` JSON, `callback_policy` JSON, `updated_at` DATETIME NOT NULL, `vpbx_user_uid` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `cc_subjects` (`uid` INTEGER auto_increment , `name` VARCHAR(255) NOT NULL, `sort_order` INTEGER DEFAULT 0, `is_active` TINYINT(1) DEFAULT true, PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `cdr` (`calldate` VARCHAR(80), `clid` VARCHAR(80) NOT NULL DEFAULT '', `src` VARCHAR(80) NOT NULL DEFAULT '', `usrc` VARCHAR(80) NOT NULL DEFAULT '', `dst` VARCHAR(80) NOT NULL DEFAULT '', `dcontext` VARCHAR(80) NOT NULL DEFAULT '', `channel` VARCHAR(80) NOT NULL DEFAULT '', `dstchannel` VARCHAR(80) NOT NULL DEFAULT '', `lastapp` VARCHAR(80) NOT NULL DEFAULT '', `lastdata` VARCHAR(80) NOT NULL DEFAULT '', `duration` INTEGER NOT NULL DEFAULT 0, `billsec` INTEGER NOT NULL DEFAULT 0, `disposition` VARCHAR(45) NOT NULL DEFAULT '', `uniqueid` VARCHAR(80) NOT NULL , `linkedid` VARCHAR(80) NOT NULL DEFAULT '', `userfield` VARCHAR(255), `dialednum` VARCHAR(20), `transid` VARCHAR(80), `record` VARCHAR(255), `vpbx_user_uid` INTEGER DEFAULT 0, `useruid` INTEGER, `dstuseruid` INTEGER, PRIMARY KEY (`uniqueid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `cloud_settings` (`id` INTEGER auto_increment , `key` VARCHAR(128) NOT NULL UNIQUE, `value` TEXT, `description` VARCHAR(255), `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL, PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `conference_guest_tokens` (`uid` INTEGER auto_increment , `room_uid` INTEGER NOT NULL, `token` VARCHAR(64) NOT NULL, `kind` ENUM('shared_link', 'named_invite') NOT NULL, `invite_name` VARCHAR(255), `expires_at` DATETIME, `revoked_at` DATETIME, `last_used_at` DATETIME, `display_name` VARCHAR(64), `sip_id` VARCHAR(64), `created_at` DATETIME NOT NULL, PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `conference_meeting_participants` (`uid` INTEGER auto_increment , `meeting_uid` INTEGER NOT NULL, `display_name` VARCHAR(255) NOT NULL, `role` ENUM('owner', 'moderator', 'participant') NOT NULL DEFAULT 'participant', `is_guest` TINYINT(1) NOT NULL DEFAULT false, `joined_at` DATETIME NOT NULL, `left_at` DATETIME, `caller_id_num` VARCHAR(64), `uniqueid` VARCHAR(64), `channel` VARCHAR(64), PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `conference_meetings` (`uid` INTEGER auto_increment , `room_uid` INTEGER NOT NULL, `started_at` DATETIME NOT NULL, `ended_at` DATETIME, `has_recording` TINYINT(1) NOT NULL DEFAULT false, `recording_file_rel` VARCHAR(512), PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `conference_room_moderators` (`uid` INTEGER auto_increment , `room_uid` INTEGER NOT NULL, `endpoint_ref` VARCHAR(64) NOT NULL, `role` ENUM('owner', 'moderator') NOT NULL DEFAULT 'moderator', PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `conference_rooms` (`uid` INTEGER auto_increment , `vpbx_user_uid` INTEGER NOT NULL, `number` VARCHAR(32) NOT NULL, `name` VARCHAR(255) NOT NULL, `kind` ENUM('permanent', 'ephemeral') NOT NULL DEFAULT 'permanent', `entry_strictness` ENUM('token_name', 'token_name_pin', 'token_name_pin_moderator') NOT NULL DEFAULT 'token_name', `pin` VARCHAR(32), `wait_marked` TINYINT(1) NOT NULL DEFAULT false, `end_marked` TINYINT(1) NOT NULL DEFAULT false, `record_mode` ENUM('off', 'auto', 'button', 'both') NOT NULL DEFAULT 'off', `notify_recording` TINYINT(1) NOT NULL DEFAULT true, `invite_external_scope` ENUM('owner', 'moderator', 'anyone') NOT NULL DEFAULT 'owner', `tariff_max_participants` INTEGER, `musiconhold` VARCHAR(128), `announce_join_leave` TINYINT(1) NOT NULL DEFAULT false, `created_by` INTEGER, `created_at` DATETIME, `updated_at` DATETIME, PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `context_includes` (`uid` INTEGER auto_increment , `context_uid` INTEGER NOT NULL, `include_uid` INTEGER NOT NULL, `priority` INTEGER NOT NULL DEFAULT 0, `user_uid` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `contexts` (`uid` INTEGER auto_increment , `name` VARCHAR(128) NOT NULL, `comment` VARCHAR(128) NOT NULL DEFAULT '', `user_uid` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `device_tokens` (`id` INTEGER auto_increment , `user_uid` INTEGER NOT NULL, `tenant_id` INTEGER NOT NULL, `token` VARCHAR(4096) NOT NULL, `platform` VARCHAR(32) DEFAULT NULL, `created_at` DATETIME, `updated_at` DATETIME, PRIMARY KEY (`id`), UNIQUE INDEX `uq_device_tokens_user_tenant` (`user_uid`, `tenant_id`), INDEX `idx_device_tokens_tenant` (`tenant_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `directories` (`uid` INTEGER auto_increment , `user_uid` INTEGER NOT NULL, `name` VARCHAR(255) NOT NULL, `description` VARCHAR(255) NOT NULL DEFAULT '', `lookup_field_uid` INTEGER DEFAULT NULL, `key_normalization` VARCHAR(16) NOT NULL DEFAULT 'none', `revision` INTEGER NOT NULL DEFAULT 0, `created_at` DATETIME, `updated_at` DATETIME, PRIMARY KEY (`uid`), INDEX `idx_directories_user_uid` (`user_uid`), UNIQUE INDEX `uq_directories_tenant_name` (`user_uid`, `name`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `directory_fields` (`uid` INTEGER auto_increment , `directory_uid` INTEGER NOT NULL, `key` VARCHAR(64) NOT NULL, `label` VARCHAR(255) NOT NULL, `type` VARCHAR(16) NOT NULL, `required` TINYINT(1) NOT NULL DEFAULT false, `position` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (`uid`), FOREIGN KEY (`directory_uid`) REFERENCES `directories` (`uid`) ON DELETE NO ACTION ON UPDATE CASCADE, UNIQUE INDEX `uq_directory_fields_key` (`directory_uid`, `key`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `directory_records` (`uid` INTEGER auto_increment , `directory_uid` INTEGER NOT NULL, `lookup_value` VARCHAR(255) NOT NULL, `normalized_lookup_value` VARCHAR(255) NOT NULL, `match_kind` VARCHAR(24) NOT NULL, `priority` INTEGER NOT NULL, `values` JSON NOT NULL, `comment` VARCHAR(255) NOT NULL DEFAULT '', `created_at` DATETIME, `updated_at` DATETIME, PRIMARY KEY (`uid`), FOREIGN KEY (`directory_uid`) REFERENCES `directories` (`uid`) ON DELETE NO ACTION ON UPDATE CASCADE, UNIQUE INDEX `uq_directory_exact_key` (`directory_uid`, `normalized_lookup_value`, `match_kind`), INDEX `idx_directory_patterns` (`directory_uid`, `match_kind`, `priority`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `hub_module_pages` (`id` INTEGER auto_increment , `hub_code` VARCHAR(64) NOT NULL, `page_code` VARCHAR(64) NOT NULL, `path` VARCHAR(255), `sort_order` INTEGER DEFAULT 0, PRIMARY KEY (`id`), FOREIGN KEY (`hub_code`) REFERENCES `hub_modules` (`code`) ON DELETE NO ACTION ON UPDATE CASCADE, UNIQUE INDEX `uq_hub_module_page` (`hub_code`, `page_code`), INDEX `idx_hub_module_pages_hub` (`hub_code`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
