CREATE TABLE IF NOT EXISTS `ivrs` (`uid` INTEGER auto_increment , `name` VARCHAR(255) NOT NULL DEFAULT '', `timeout` VARCHAR(255), `timeout_response` VARCHAR(255), `timeout_digit` VARCHAR(255), `max_count` INTEGER NOT NULL DEFAULT 0, `active` TINYINT NOT NULL DEFAULT 1, `direct_dial` TINYINT NOT NULL DEFAULT 1, `prompts` JSON, `menu_items` JSON, `user_uid` INTEGER NOT NULL DEFAULT 0, `created_at` DATETIME, `updated_at` DATETIME, PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `komandor_claims` (`uid` BIGINT auto_increment , `operator_id` INTEGER, `operator_name` VARCHAR(255), `request_date` DATETIME NOT NULL, `call_uniqueid` VARCHAR(128), `request_number` VARCHAR(64) UNIQUE, `store_id` INTEGER, `store_code` VARCHAR(64), `store_name` VARCHAR(512), `store_address` VARCHAR(512), `directors` JSON, `zdf` JSON, `extra_recipients` JSON, `extra_emails` TEXT, `channel` VARCHAR(64), `topic` VARCHAR(255), `subtopic` VARCHAR(255), `description` TEXT, `contact_info` TEXT, `client_phone` VARCHAR(32), `client_email` VARCHAR(255), `sentiment` VARCHAR(16) NOT NULL DEFAULT 'neutral', `department_log` JSON, `customer_response` TEXT, `attachment_name` VARCHAR(255), `dept_attachment_name` VARCHAR(255), `request_status` VARCHAR(20) NOT NULL DEFAULT 'new', `sms_status` VARCHAR(20) NOT NULL DEFAULT 'not_sent', `email_status` VARCHAR(20) NOT NULL DEFAULT 'not_sent', `store_email_status` VARCHAR(20) NOT NULL DEFAULT 'not_sent', `user_uid` INTEGER NOT NULL DEFAULT 0, `created_at` DATETIME, `updated_at` DATETIME, PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
