T, `media_encryption_optimistic` TEXT, `rpid_immediate` TEXT, `g726_non_standard` TEXT, `rtp_keepalive` INTEGER, `rtp_timeout` INTEGER, `rtp_timeout_hold` INTEGER, `bind_rtp_to_media_address` TEXT, `voicemail_extension` TEXT, `mwi_subscribe_replaces_unsolicited` TEXT, `deny` VARCHAR(95), `permit` VARCHAR(95), `acl` TEXT, `contact_deny` VARCHAR(95), `contact_permit` VARCHAR(95), `contact_acl` TEXT, `subscribe_context` TEXT, `fax_detect_timeout` INTEGER, `contact_user` VARCHAR(80), `preferred_codec_only` TEXT, `asymmetric_rtp_codec` TEXT, `rtcp_mux` TEXT, `allow_overlap` TEXT, `refer_blind_progress` TEXT, `notify_early_inuse_ringing` TEXT, `max_audio_streams` INTEGER, `max_video_streams` INTEGER, `webrtc` TEXT, `dtls_fingerprint` TEXT, `incoming_mwi_mailbox` TEXT, `bundle` TEXT, `dtls_auto_generate_cert` TEXT, `follow_early_media_fork` TEXT, `accept_multiple_sdp_answers` TEXT, `suppress_q850_reason_headers` TEXT, `trust_connected_line` TEXT, `send_connected_line` TEXT, `ignore_183_without_sdp` TEXT, `codec_prefs_incoming_offer` VARCHAR(128), `codec_prefs_outgoing_offer` VARCHAR(128), `codec_prefs_incoming_answer` VARCHAR(128), `codec_prefs_outgoing_answer` VARCHAR(128), `stir_shaken` TEXT, `send_history_info` TEXT, `allow_unauthenticated_options` TEXT, `t38_bind_udptl_to_media_address` TEXT, `geoloc_incoming_call_profile` VARCHAR(80), `geoloc_outgoing_call_profile` VARCHAR(80), `incoming_call_offer_pref` TEXT, `outgoing_call_offer_pref` TEXT, `stir_shaken_profile` VARCHAR(80), `security_negotiation` TEXT, `security_mechanisms` VARCHAR(512), `send_aoc` TEXT, `overlap_context` VARCHAR(80), `media_use_received_transport` TEXT, `force_avp` TEXT, `message_context` TEXT, `tenantid` VARCHAR(80), `suppress_moh_on_sendonly` TEXT, `follow_redirect_methods` VARCHAR(95), `department` VARCHAR(255) DEFAULT '', `provision_enabled` TINYINT(1) DEFAULT false, `mac_address` VARCHAR(100) DEFAULT '', `provision_template_id` INTEGER, `pv_vars` TEXT, PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `ps_registrations` (`id` VARCHAR(40) , `auth_rejection_permanent` ENUM('yes', 'no'), `client_uri` VARCHAR(255), `contact_user` VARCHAR(40), `expiration` INTEGER, `max_retries` INTEGER, `outbound_auth` VARCHAR(40), `outbound_proxy` VARCHAR(40), `retry_interval` INTEGER, `forbidden_retry_interval` INTEGER, `server_uri` VARCHAR(255), `transport` VARCHAR(40), `support_path` ENUM('yes', 'no'), `line` ENUM('yes', 'no'), `endpoint` VARCHAR(40), `type` VARCHAR(40) DEFAULT 'registration', PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `queue_members_table` (`uniqueid` INTEGER UNSIGNED auto_increment , `membername` VARCHAR(40), `queue_name` VARCHAR(128) NOT NULL, `interface` VARCHAR(128) NOT NULL, `penalty` INTEGER DEFAULT 0, `paused` INTEGER DEFAULT 0, `reason_paused` VARCHAR(128), `wrapuptime` INTEGER, `state_interface` VARCHAR(128), `vpbx_user_uid` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (`uniqueid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `queue_table` (`name` VARCHAR(128) , `musiconhold` VARCHAR(128), `announce` VARCHAR(128), `context` VARCHAR(128), `timeout` INTEGER, `strategy` VARCHAR(128), `retry` INTEGER, `wrapuptime` INTEGER, `maxlen` INTEGER, `servicelevel` INTEGER, `weight` INTEGER, `joinempty` VARCHAR(128), `leavewhenempty` VARCHAR(128), `ringinuse` TINYINT(1), `autofill` VARCHAR(8), `announce_frequency` INTEGER, `announce_holdtime` VARCHAR(128), `announce_round_seconds` INTEGER, `periodic_announce` VARCHAR(50), `periodic_announce_frequency` INTEGER, `queue_youarenext` VARCHAR(128), `queue_thereare` VARCHAR(128), `queue_callswaiting` VARCHAR(128), `queue_holdtime` VARCHAR(128), `queue_minutes` VARCHAR(128), `queue_seconds` VARCHAR(128), `queue_lessthan` VARCHAR(128), `queue_thankyou` VARCHAR(128), `queue_reporthold` VARCHAR(128), `monitor_format` VARCHAR(128), `monitor_join` TINYINT(1), `memberdelay` INTEGER, `timeoutrestart` TINYINT(1), `reportholdtime` TINYINT(1), `eventmemberstatus` TINYINT(1), `eventwhencalled` TINYINT(1), `setinterfacevar` TINYINT(1), `display_name` VARCHAR(255), `vpbx_user_uid` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (`name`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `role_start_defaults` (`id` INTEGER auto_increment , `user_level` INTEGER NOT NULL UNIQUE, `start_path` VARCHAR(255) NOT NULL, PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `roles` (`id` INTEGER auto_increment , `name` VARCHAR(255), `role` TEXT, `comment` VARCHAR(255), `vpbx_user_uid` INTEGER DEFAULT 0, `createdAt` DATETIME NOT NULL, `updatedAt` DATETIME NOT NULL, PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `route_directory_bindings` (`uid` INTEGER auto_increment , `route_uid` INTEGER NOT NULL, `directory_uid` INTEGER NOT NULL, `position` INTEGER NOT NULL DEFAULT 0, `key_source` JSON NOT NULL, `match_mode` VARCHAR(16) NOT NULL DEFAULT 'on_match', `behavior_type` VARCHAR(32) NOT NULL, `behavior_params` JSON, `actions` JSON, `user_uid` INTEGER NOT NULL, PRIMARY KEY (`uid`), FOREIGN KEY (`route_uid`) REFERENCES `routes` (`uid`) ON DELETE NO ACTION ON UPDATE CASCADE, FOREIGN KEY (`directory_uid`) REFERENCES `directories` (`uid`) ON DELETE CASCADE ON UPDATE CASCADE, INDEX `idx_rdb_user_uid` (`user_uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `route_templates` (`uid` INTEGER auto_increment , `name` VARCHAR(255) NOT NULL, `description` VARCHAR(512) NOT NULL DEFAULT '', `actions` JSON NOT NULL, `slots` JSON NOT NULL, `vpbx_user_uid` INTEGER DEFAULT NULL, `created_at` DATETIME, `updated_at` DATETIME, PRIMARY KEY (`uid`), INDEX `idx_route_templates_vpbx_user_uid` (`vpbx_user_uid`), UNIQUE INDEX `uq_route_templates_tenant_name` (`vpbx_user_uid`, `name`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `routes` (`uid` INTEGER auto_increment , `context_uid` INTEGER NOT NULL, `name` VARCHAR(255) NOT NULL DEFAULT '', `extensions` JSON NOT NULL, `priority` INTEGER NOT NULL DEFAULT 0, `active` TINYINT NOT NULL DEFAULT 1, `options` JSON, `webhooks` JSON, `actions` JSON NOT NULL, `raw_dialplan` TEXT, `user_uid` INTEGER NOT NULL DEFAULT 0, `created_at` DATETIME, `updated_at` DATETIME, PRIMARY KEY (`uid`), FOREIGN KEY (`context_uid`) REFERENCES `contexts` (`uid`) ON DELETE NO ACTION ON UPDATE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `service_requests` (`uid` BIGINT auto_increment , `operator_id` INTEGER, `operator_name` VARCHAR(255), `call_received_at` DATETIME NOT NULL, `call_uniqueid` VARCHAR(128), `request_number` VARCHAR(64) UNIQUE, `counterparty_type` VARCHAR(20) NOT NULL DEFAULT 'individual', `counterparty_name` VARCHAR(512), `account_or_inn` VARCHAR(64), `phone` VARCHAR(32), `territorial_zone` VARCHAR(128), `locality` VARCHAR(255), `district` VARCHAR(128), `address` VARCHAR(512), `topic` VARCHAR(128), `comment` TEXT, `production_comment` TEXT, `schedule_comment` TEXT, `sms_status` VARCHAR(20) NOT NULL DEFAULT 'not_sent', `scheduled_date` DATETIME, `request_status` VARCHAR(20) NOT NULL DEFAULT 'new', `user_uid` INTEGER NOT NULL DEFAULT 0, `created_at` DATETIME, `updated_at` DATETIME, PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `stt_engines` (`uid` INTEGER auto_increment , `name` VARCHAR(128) NOT NULL, `type` VARCHAR(32) NOT NULL DEFAULT 'custom', `token` TEXT, `settings` JSON, `custom_url` VARCHAR(512), `auth_mode` VARCHAR(32) DEFAULT 'none', `custom_headers` JSON, `user_uid` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `system_settings` (`uid` INTEGER auto_increment , `key` VARCHAR(128) NOT NULL UNIQUE, `value` TEXT, `category` VARCHAR(64) NOT NULL DEFAULT 'general', `updated_at` DATETIME, PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `tenant_modules` (`id` INTEGER auto_increment , `tenant_id` INTEGER NOT NULL, `module_code` VARCHAR(64) NOT NULL, `status` ENUM('active', 'inactive', 'trial', 'expired') DEFAULT 'active', `activated_at` DATETIME, `expires_at` DATETIME, `billing_cycle` ENUM('monthly', 'yearly', 'lifetime') DEFAULT 'monthly', `last_billed_at` DATETIME, `config` JSON, PRIMARY KEY (`id`), UNIQUE INDEX `uq_tenant_module` (`tenant_id`, `module_code`), INDEX `idx_tm_tenant` (`tenant_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `tenant_role_start` (`id` INTEGER auto_increment , `tenant_id` INTEGER NOT NULL, `user_level` INTEGER NOT NULL, `start_path` VARCHAR(255) NOT NULL, PRIMARY KEY (`id`), UNIQUE INDEX `uq_tenant_role_start` (`tenant_id`, `user_level`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `tenant_settings` (`id` INTEGER auto_increment , `vpbx_user_uid` INTEGER NOT NULL, `key` VARCHAR(128) NOT NULL, `value` TEXT, `category` VARCHAR(64) DEFAULT 'general', PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `tenants` (`id` INTEGER auto_increment , `uid` VARCHAR(36) NOT NULL, `name` VARCHAR(255) NOT NULL, `slug` VARCHAR(128), `owner_user_id` INTEGER NOT NULL, `vpbx_user_uid` INTEGER NOT NULL, `status` ENUM('trial', 'active', 'suspended', 'cancelled') DEFAULT 'trial', `trial_ends_at` DATETIME, `email` VARCHAR(255), `phone` VARCHAR(32), `company_inn` VARCHAR(32), `max_extensions` INTEGER DEFAULT 10, `max_trunks` INTEGER DEFAULT 2, `max_queues` INTEGER DEFAULT 3, `created_by` INTEGER, `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL, PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `time_groups` (`uid` INTEGER auto_increment , `name` VARCHAR(100) NOT NULL, `comment` VARCHAR(255) DEFAULT '', `intervals` JSON NOT NULL, `user_uid` INTEGER NOT NULL DEFAULT 0, `created_at` DATETIME, `updated_at` DATETIME, PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `tts_engines` (`uid` INTEGER auto_increment , `name` VARCHAR(128) NOT NULL, `type` VARCHAR(32) NOT NULL DEFAULT 'custom', `token` TEXT, `settings` JSON, `custom_url` VARCHAR(512), `auth_mode` VARCHAR(32) DEFAULT 'none', `custom_headers` JSON, `user_uid` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `user_sessions` (`id` INTEGER auto_increment , `user_id` INTEGER NOT NULL, `refreshToken` VARCHAR(512) NOT NULL, `userAgent` TEXT, `ipAddress` VARCHAR(45), `expiresAt` BIGINT NOT NULL, `createdAt` DATETIME NOT NULL, `updatedAt` DATETIME NOT NULL, PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `users` (`uniqueid` INTEGER auto_increment , `login` VARCHAR(255), `name` VARCHAR(255), `passwd` VARCHAR(255), `email` VARCHAR(255), `exten` VARCHAR(255), `level` INTEGER DEFAULT 2, `role` INTEGER, `numbers_id` INTEGER, `permit_extens` VARCHAR(255), `listbook_edit` INTEGER DEFAULT 0, `oper_chanspy` INTEGER DEFAULT 0, `outbound_posttime` INTEGER DEFAULT 0, `suspension_time` INTEGER DEFAULT 0, `inactive_time` INTEGER DEFAULT 0, `vpbx_user_uid` INTEGER DEFAULT 0, `activationCode` VARCHAR(255), `activationExpires` BIGINT, `isActivated` TINYINT(1) DEFAULT false, `avatar` VARCHAR(255), `createdAt` DATETIME NOT NULL, `updatedAt` DATETIME NOT NULL, PRIMARY KEY (`uniqueid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `vm_access_tokens` (`uid` INTEGER auto_increment , `token` VARCHAR(64) NOT NULL, `message_uid` INTEGER NOT NULL, `vpbx_user_uid` INTEGER NOT NULL DEFAULT 0, `expires_at` DATETIME NOT NULL, `revoked_at` DATETIME, `created_at` DATETIME NOT NULL, PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `voice_robot_cdr` (`uid` BIGINT auto_increment , `robot_id` INTEGER NOT NULL, `robot_name` VARCHAR(255), `call_uniqueid` VARCHAR(128), `channel_id` VARCHAR(255), `session_id` VARCHAR(255), `caller_id` VARCHAR(64), `caller_name` VARCHAR(128), `started_at` DATETIME NOT NULL, `ended_at` DATETIME, `duration_seconds` INTEGER NOT NULL DEFAULT 0, `disposition` VARCHAR(32) NOT NULL DEFAULT 'completed', `last_action` VARCHAR(64), `transfer_target` VARCHAR(128), `total_steps` INTEGER NOT NULL DEFAULT 0, `matched_keywords_count` INTEGER NOT NULL DEFAULT 0, `no_match_count` INTEGER NOT NULL DEFAULT 0, `avg_confidence` DECIMAL(5,2), `collected_slots` JSON, `transcript` TEXT, `tags` JSON, `user_uid` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `voice_robot_data_lists` (`uid` INTEGER auto_increment , `robot_id` INTEGER NOT NULL, `name` VARCHAR(255) NOT NULL, `description` TEXT, `columns` JSON NOT NULL, `rows` JSON NOT NULL, `user_uid` INTEGER NOT NULL DEFAULT 0, `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL, PRIMARY KEY (`uid`), FOREIGN KEY (`robot_id`) REFERENCES `voice_robots` (`uid`) ON DELETE CASCADE ON UPDATE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `voice_robot_keyword_groups` (`uid` INTEGER auto_increment , `robot_id` INTEGER NOT NULL, `name` VARCHAR(255) NOT NULL, `description` TEXT, `priority` INTEGER NOT NULL DEFAULT 0, `active` TINYINT NOT NULL DEFAULT 1, `is_global` TINYINT NOT NULL DEFAULT 0, `user_uid` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (`uid`), FOREIGN KEY (`robot_id`) REFERENCES `voice_robots` (`uid`) ON DELETE CASCADE ON UPDATE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `voice_robot_keywords` (`uid` INTEGER auto_increment , `group_id` INTEGER NOT NULL, `keywords` TEXT NOT NULL, `negative_keywords` JSON, `synonyms` JSON, `actions` JSON, `bot_action` JSON, `priority` INTEGER NOT NULL DEFAULT 0, `max_repeats` INTEGER NOT NULL DEFAULT 0, `escalation_action` JSON, `comment` VARCHAR(512), `tag` VARCHAR(255), `user_uid` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (`uid`), FOREIGN KEY (`group_id`) REFERENCES `voice_robot_keyword_groups` (`uid`) ON DELETE CASCADE ON UPDATE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `voice_robot_logs` (`uid` INTEGER auto_increment , `robot_id` INTEGER, `call_uniqueid` VARCHAR(128), `session_id` VARCHAR(255), `channel_id` VARCHAR(255), `caller_id` VARCHAR(255), `step_number` INTEGER NOT NULL DEFAULT 0, `matched_group_id` INTEGER, `recognized_text` TEXT, `raw_stt_json` JSON, `audio_file_path` VARCHAR(512), `matched_keyword_id` INTEGER, `match_confidence` DECIMAL(5,2), `action_taken` VARCHAR(512), `stt_duration_ms` INTEGER, `matching_score` FLOAT, `duration_ms` INTEGER, `ai_response` TEXT, `flow_action` JSON, `user_uid` INTEGER, `timestamp` DATETIME, PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `voice_robots` (`uid` INTEGER auto_increment , `name` VARCHAR(255) NOT NULL, `description` TEXT, `active` TINYINT NOT NULL DEFAULT 1, `language` VARCHAR(16) NOT NULL DEFAULT 'ru-RU', `stt_engine_id` INTEGER, `tts_engine_id` INTEGER, `greeting_prompts` JSON, `greeting_tts_text` TEXT, `initial_group_id` INTEGER, `vad_config` JSON, `fallback_action` JSON, `fallback_bot_action` JSON, `max_retries_action` JSON, `max_retries_bot_action` JSON, `max_conversation_steps` INTEGER NOT NULL DEFAULT 0, `silence_timeout_seconds` INTEGER NOT NULL DEFAULT 15, `max_inactivity_repeats` INTEGER NOT NULL DEFAULT 3, `webhook_url` VARCHAR(512), `webhook_method` VARCHAR(8) NOT NULL DEFAULT 'POST', `telegram_chat_id` VARCHAR(128), `email_notify` VARCHAR(255), `external_host` VARCHAR(255), `tts_mode` VARCHAR(20) NOT NULL DEFAULT 'batch', `tts_cache_max_age_days` INTEGER NOT NULL DEFAULT 0, `stt_mode` VARCHAR(20) NOT NULL DEFAULT 'hybrid', `user_uid` INTEGER NOT NULL DEFAULT 0, `created_at` DATETIME, `updated_at` DATETIME, PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `voicemail_messages` (`uid` INTEGER auto_increment , `vpbx_user_uid` INTEGER NOT NULL DEFAULT 0, `uniqueid` VARCHAR(128) NOT NULL, `file_rel` VARCHAR(512) NOT NULL, `record_status` VARCHAR(32) NOT NULL DEFAULT '', `caller_id` VARCHAR(64) NOT NULL DEFAULT '', `exten` VARCHAR(64) NOT NULL DEFAULT '', `duration_sec` INTEGER, `notify_status` VARCHAR(16) NOT NULL DEFAULT 'pending', `transcript_status` VARCHAR(16) NOT NULL DEFAULT 'pending', `notify_attempts` INTEGER NOT NULL DEFAULT 0, `transcript_attempts` INTEGER NOT NULL DEFAULT 0, `next_notify_at` DATETIME, `scan_locked_until` DATETIME, `transcript` TEXT, `summary` TEXT, `notify_error` TEXT, `notify_dispatch` TEXT, `created_at` DATETIME NOT NULL, PRIMARY KEY (`uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS `webhook_failures` (`id` INTEGER UNSIGNED auto_increment , `route_uid` VARCHAR(64) NOT NULL, `event` VARCHAR(32) NOT NULL, `url` VARCHAR(512) NOT NULL, `payload` JSON NOT NULL, `headers` JSON NOT NULL, `error` TEXT, `attempts` TINYINT UNSIGNED DEFAULT 3, `failed_at` DATETIME, `retried_at` DATETIME, `resolved` TINYINT(1) DEFAULT false, PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
SET FOREIGN_KEY_CHECKS=1;
